17	        long count = ownerRepository.findAll().stream()
18	                .filter(existing -> !existing.getId().equals(owner.getId()))
19	                .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
20	                        && equalsIgnoreCase(existing.getLastName(), lastName))
21	                .count();
22	        owner.setNamesakeCount((int) count);
23	    }
24	
25	    private static boolean equalsIgnoreCase(String a, String b) {
26	        return a == null ? b == null : a.equalsIgnoreCase(b);
27	    }
28	}
